import { useEffect, useRef, useState, type FormEvent, type ReactNode } from "react";
import { post, request, type AppState, type AssessmentTask, type MeProfile, type ModelConnection, type ModelProvider, type Skill, type SkillImport, type VirtualParticipant, type VirtualSession } from "./api";
import type { Shared } from "./App";
import { ResearchIndicator, ResearchNotice, ResearchSourcesButton, WebSettings } from "./WebResearch";
import { MessageSoundControl } from "./MessageSoundControl";
import { notifyIncomingMessages } from "./messageSound";

const providerNames: Record<string,string> = {openai:"OpenAI",claude:"Claude",anthropic:"Claude",gemini:"Gemini",deepseek:"DeepSeek",qwen:"通义千问",glm:"智谱",kimi:"Kimi",doubao:"豆包",custom:"自定义 OpenAI 兼容接口"};
const statusNames: Record<string,string> = {HYPOTHESIS:"待验证的线索",SUPPORTED:"有证据支持",CONFLICTED:"存在不同线索",INSUFFICIENT:"证据仍不足",INTERVENING:"等待本人干预",DRAFT:"待评草稿",PENDING:"待评草稿",READY:"评审通过",PASSED:"评审通过",ACTIVE:"已添加",ADDED:"已添加",RUNNING:"进行中",NEEDS_ANSWERS:"等待本人作答",NEEDS_REVIEW:"等待本人核验",NEEDS_CONFIRMATION:"等待确认报告",NOT_PASSED:"本轮未达标",FAILED:"评估未完成",INCOMPLETE:"评估未完成",INTERRUPTED:"已中断，可继续",CANCELLED:"已取消",COMPLETED:"已完成",CREATED:"尚未开始",PAUSED:"已暂停",PAUSED_LIMIT:"额度已用完，已暂停",STOPPED:"已停止",INVALIDATED:"许可或来源已失效",DELETED:"已移除"};
function status(value:string) { return statusNames[value] || value; }
function virtualStatus(value:string) { return ["FAILED","INCOMPLETE"].includes(value)?"本轮发言未完成":status(value); }
function errorText(error:unknown) {return error instanceof Error?error.message:"操作没有完成，请重试。";}
const id = encodeURIComponent;
const assessmentName = (task:AssessmentTask) => task.kind==="QUALITY" ? task.subject_type==="USER_SKILL" ? "本人 Skill 资料质量评估" : "人物资料质量评估" : "严格个人校验";
export function modelConfigured(data:AppState) {const connections=data.upgrade?.connections||[];const active=connections.find(connection=>connection.is_default)||connections[0];return active?.key_status==="CONFIGURED";}

export function Avatar({url,name,size=52}:{url?:string;name?:string;size?:number}) {return <span className="up-avatar" style={{width:size,height:size}}>{url?<img src={url} alt=""/>:<span>{name?.slice(0,1)||"我"}</span>}</span>;}
export function Modal({title,children,close,wide=false}:{title:string;children:ReactNode;close:()=>void;wide?:boolean}) {
  const ref=useRef<HTMLDialogElement>(null);
  useEffect(()=>{const previous=document.activeElement as HTMLElement|null;ref.current?.showModal();return ()=>{ref.current?.close();previous?.focus();};},[]);
  return <dialog className={`upgrade-dialog ${wide?"upgrade-dialog-wide":""}`} ref={ref} onCancel={e=>{e.preventDefault();close();}} aria-label={title}><header><h2>{title}</h2><button className="icon-button" aria-label={`关闭${title}`} onClick={close}>✕</button></header><div className="upgrade-dialog-content">{children}</div></dialog>;
}
async function imageData(file:File) {
  if(!["image/png","image/jpeg","image/webp"].includes(file.type))throw new Error("请选择 PNG、JPEG 或 WebP 图片。");
  if(file.size>5*1024*1024)throw new Error("头像不能超过 5MB，请换一张小一些的图片。");
  return new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(new Error("图片读取失败，请重新选择。"));reader.readAsDataURL(file);});
}
export function AvatarControls({path,act}:{path:string;act:Shared["act"]}) {
  const input=useRef<HTMLInputElement>(null);const [error,setError]=useState("");
  return <div className="up-avatar-actions"><input ref={input} type="file" accept="image/png,image/jpeg,image/webp" className="sr-only" aria-label="上传自定义头像" onChange={async e=>{const file=e.target.files?.[0];if(!file)return;setError("");try{const data_url=await imageData(file);await act("头像已更新",()=>post(`${path}/avatar`,{data_url}));}catch(reason){setError(errorText(reason));}e.target.value="";}}/><button className="text-button" onClick={()=>input.current?.click()}>换头像</button><button className="text-button" onClick={()=>void act("已恢复默认头像",()=>post(`${path}/avatar/reset`))}>恢复默认头像</button>{error&&<span className="up-error" role="alert">{error}</span>}</div>;
}

interface ConnectionValidation {
  status: "TEST_FAILED" | "SAVE_FAILED" | "ADDED" | "UPDATED";
  tested: boolean;
  saved: boolean;
  provider: string;
  model: string;
  elapsed_ms: number;
  message: string;
  connection?: ModelConnection;
}

export function ModelSettings({data,act,refresh,firstRun=false,onDone}:{data:Shared["data"];act:Shared["act"];refresh:Shared["refresh"];firstRun?:boolean;onDone?:()=>void}) {
  const connections=data.upgrade?.connections||[];
  const providers:ModelProvider[]=data.upgrade?.providers?.length?data.upgrade.providers:Object.keys(providerNames).filter(k=>k!=="anthropic").map(key=>({id:key,name:providerNames[key]}));
  const initial=connections.find(connection=>connection.is_default||connection.default)||connections[0];
  const [editing,setEditing]=useState(initial?.id||"");const [provider,setProvider]=useState(initial?.provider||providers[0]?.id||"openai");const [model,setModel]=useState(initial?.model||"");const [label,setLabel]=useState(initial?.label||"");
  const [apiKey,setApiKey]=useState("");const [remember,setRemember]=useState(Boolean(initial?.remember));const [baseUrl,setBaseUrl]=useState(initial?.base_url||"");const [region,setRegion]=useState(initial?.region||"");const [workspace,setWorkspace]=useState(initial?.workspace_id||"");const [protocol,setProtocol]=useState(initial?.protocol||"");
  const [savedKey,setSavedKey]=useState<ModelConnection|null>(initial||null);const [replacingKey,setReplacingKey]=useState(Boolean(initial&&initial.key_status!=="CONFIGURED"));
  const [models,setModels]=useState<string[]>([]);const [discovering,setDiscovering]=useState(false);const [busy,setBusy]=useState(false);const [error,setError]=useState("");const [info,setInfo]=useState("");const [validation,setValidation]=useState<ConnectionValidation|null>(null);
  const revision=useRef(0);const running=useRef(false);const mounted=useRef(true);const validationPanel=useRef<HTMLElement>(null);
  useEffect(()=>{mounted.current=true;return()=>{mounted.current=false;revision.current++;};},[]);
  useEffect(()=>{if(validation&&validationPanel.current){validationPanel.current.focus({preventScroll:true});validationPanel.current.scrollIntoView({block:"center",behavior:window.matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"});}},[validation,connections.length]);
  function changed(update:()=>void){revision.current++;setValidation(null);setError("");setInfo("");update();}
  function clear(){changed(()=>{setEditing("");setProvider(providers[0]?.id||"openai");setModel("");setLabel("");setApiKey("");setRemember(false);setBaseUrl("");setRegion("");setWorkspace("");setProtocol("");setModels([]);setSavedKey(null);setReplacingKey(false);});}
  function edit(connection:ModelConnection){changed(()=>{setEditing(connection.id);setProvider(connection.provider);setModel(connection.model);setLabel(connection.label||"");setApiKey("");setRemember(Boolean(connection.remember));setBaseUrl(connection.base_url||"");setRegion(connection.region||"");setWorkspace(connection.workspace_id||"");setProtocol(connection.protocol||"");setModels([]);setSavedKey(connection);setReplacingKey(connection.key_status!=="CONFIGURED");});}
  async function save() {
    if(running.current)return;
    running.current=true;const submittedRevision=revision.current;setBusy(true);setError("");setInfo("");setValidation(null);
    try{
      const payload={...(editing?{connection_id:editing}:{}),provider,model,label,remember,...(apiKey?{api_key:apiKey}:{}),base_url:baseUrl,region,workspace_id:workspace,protocol};
      const result=await post<ConnectionValidation>("/model-connection-validations",payload);
      if(!mounted.current)return;
      if(submittedRevision!==revision.current){setInfo(result.saved?"表单已修改；上一次提交的连接已保存，当前修改尚未保存。请重新测试并保存。":"表单已修改，上一次测试结果不再适用于当前内容。请重新测试并保存。");if(result.saved)await refresh().catch(()=>{});return;}
      setValidation(result);
      if(result.saved&&result.connection){setEditing(result.connection.id);setSavedKey(result.connection);setReplacingKey(false);setApiKey("");await refresh().catch(()=>{});}
    }catch(reason){if(mounted.current&&submittedRevision===revision.current)setError(errorText(reason));}
    finally{running.current=false;if(mounted.current)setBusy(false);}
  }
  async function discoverModels(automatic=false){
    if(discovering||running.current)return;
    const requestedRevision=revision.current;setDiscovering(true);if(!automatic)setError("");
    try{
      const found=await post<(string|{id:string})[]>("/model-discovery",{...(editing?{connection_id:editing}:{}),provider,...(apiKey?{api_key:apiKey}:{}),base_url:baseUrl,region,workspace_id:workspace,protocol});
      if(!mounted.current||requestedRevision!==revision.current)return;
      setModels(found.map(item=>typeof item==="string"?item:item.id));setInfo(found.length?`已读取 ${found.length} 个模型，也可以手动填写。`:"供应商未提供模型列表，请手动填写模型 ID 并测试。");
    }catch(reason){if(mounted.current&&requestedRevision===revision.current){if(!automatic)setError(errorText(reason));setInfo("暂时未能读取模型列表，可以手动填写模型 ID 后测试。");}}
    finally{if(mounted.current)setDiscovering(false);}
  }
  const selected=providers.find((entry:ModelProvider)=>entry.id===provider);
  const specialQwen=provider==="qwen";const specialDoubao=provider==="doubao";
  const hasSavedKey=Boolean(savedKey?.key_status==="CONFIGURED");
  const keyLabel=savedKey?.storage==="OS_CREDENTIAL_STORE"?"已保存 Key":"仅本次运行有效";
  const saved=Boolean(validation?.saved);
  return <div className="model-settings">
    {firstRun&&<div className="up-intro"><span className="up-model-mark" aria-hidden="true">✦</span><h3>先连接你喜欢的模型</h3><p>填入你自己的 API Key，就可以与人物对话、评估分身。也可以稍后设置，先看看这里。</p></div>}
    {connections.length>0&&<section className="up-connections" aria-label="已保存的模型连接"><div className="up-section-title"><h3>我的连接</h3><button className="text-button" disabled={busy} onClick={clear}>新增连接</button></div>{connections.map(connection=><article className={editing===connection.id?"editing":""} key={connection.id}><div><strong>{connection.label||providerNames[connection.provider]||connection.provider}</strong><p>{connection.model}{(connection.is_default||connection.default)&&<span className="up-badge">默认</span>}</p><small>{connection.api_key_mask||"尚未配置 Key"}{connection.key_status==="CONFIGURED"?(connection.storage==="OS_CREDENTIAL_STORE"?" · 已保存 Key":" · 仅本次运行有效"):" · 请重新填写 Key"}</small></div><div className="up-connection-buttons"><button className="text-button" disabled={busy} onClick={()=>edit(connection)}>修改</button>{!connection.is_default&&!connection.default&&<button className="text-button" disabled={busy} onClick={()=>void act("默认连接已更新",()=>post(`/model-connections/${id(connection.id)}/default`))}>设为默认</button>}<button className="text-button quiet-danger" disabled={busy} onClick={()=>void act("连接已移除",async()=>{await request(`/model-connections/${id(connection.id)}`,{method:"DELETE"});if(editing===connection.id)clear();})}>移除</button></div></article>)}</section>}
    <form className="stack-form up-connection-form" onSubmit={e=>{e.preventDefault();void save();}} aria-busy={busy}>
      <div className="up-section-title"><h3>{editing?"修改连接":"添加模型连接"}</h3>{editing&&<button type="button" className="text-button" disabled={busy} onClick={clear}>取消修改</button>}</div>
      <div className="up-form-grid"><label className="field">模型供应商<select value={provider} onChange={e=>changed(()=>{setProvider(e.target.value);setProtocol("");setModels([]);setModel("");setBaseUrl("");setRegion("");setWorkspace("");})}>{providers.map((entry:ModelProvider)=><option key={entry.id} value={entry.id}>{entry.name||entry.label||providerNames[entry.id]||entry.id}</option>)}</select></label><label className="field">连接名称（可选）<input value={label} onChange={e=>changed(()=>setLabel(e.target.value))} maxLength={80} placeholder="例如：日常聊天"/></label></div>
      <label className="field">{specialDoubao?"模型或推理接入点 ID":"模型 ID"}<div className="up-input-action"><input aria-label={specialDoubao?"模型或推理接入点 ID":"模型 ID"} required value={model} list="available-models" onChange={e=>changed(()=>setModel(e.target.value))} placeholder={specialDoubao?"填入模型 ID 或 ep- 开头的接入点":"填写供应商提供的模型 ID"} autoComplete="off"/><button type="button" className="button-secondary" disabled={(!apiKey&&!hasSavedKey)||busy||discovering} onClick={()=>void discoverModels()}>{discovering?"读取中…":"读取模型"}</button></div><datalist id="available-models">{models.map(value=><option key={value} value={value}/>)}</datalist></label>
      {specialQwen&&<div className="up-form-grid"><label className="field">地区<select aria-label="地区" value={region} onChange={e=>changed(()=>setRegion(e.target.value))}><option value="">使用供应商默认地区</option><option value="cn-beijing">中国内地（北京）</option><option value="international">新加坡</option><option value="us">美国</option><option value="workspace">工作空间专用</option></select></label><label className="field">工作空间 ID（按需）<input value={workspace} onChange={e=>changed(()=>setWorkspace(e.target.value))} placeholder="工作空间要求时填写"/></label></div>}
      <details className="up-advanced" open={provider==="custom"}><summary>接口地址与协议</summary><label className="field">API 基础地址<input type="url" value={baseUrl} onChange={e=>changed(()=>setBaseUrl(e.target.value))} placeholder={selected?.base_url||"留空使用供应商默认地址"} autoComplete="off"/></label><label className="field">接口协议<select value={protocol} onChange={e=>changed(()=>setProtocol(e.target.value))}><option value="">供应商默认</option><option value="responses">Responses</option><option value="chat">Chat Completions</option><option value="messages">Messages</option><option value="generateContent">GenerateContent</option></select></label></details>
      {hasSavedKey&&!replacingKey?<section className="up-key-state" aria-label="API Key 状态"><div><strong>{keyLabel}</strong><span>{savedKey?.api_key_mask||"••••••••"}</span><small>{savedKey?.storage==="OS_CREDENTIAL_STORE"?"保存在系统安全凭据库，原始 Key 不会回显。":"本机服务退出后需重新填写。"}</small></div><button type="button" className="text-button" onClick={()=>changed(()=>setReplacingKey(true))}>更换 Key</button></section>:<label className="field">API Key<input type="password" value={apiKey} onChange={e=>changed(()=>{setApiKey(e.target.value);setModels([]);})} onBlur={()=>{if(apiKey&&!models.length&&!discovering&&!busy)void discoverModels(true);}} required={!hasSavedKey} placeholder={hasSavedKey?"填入新 Key，留空保留已有 Key":"只提交给本机服务"} autoComplete="new-password" spellCheck={false}/></label>}
      <label className="up-checkbox"><input type="checkbox" checked={remember} onChange={e=>changed(()=>setRemember(e.target.checked))}/>记住 Key，保存在系统安全凭据库</label><p className="up-note">不勾选时，仅本次服务运行可用。系统安全存储不可用时，请取消勾选后重试。Key 不会进入聊天或导出文件。</p>
      {error&&<div className="up-error" role="alert">{error}</div>}
      {validation&&<section ref={validationPanel} tabIndex={-1} className={`up-validation ${saved?"is-saved":"is-failed"}`} role={saved?"status":"alert"} aria-label="连接验证结果"><div className="up-validation-heading"><span aria-hidden="true">{saved?"✓":"!"}</span><h3>{validation.status==="ADDED"?"已添加":validation.status==="UPDATED"?"已更新":validation.status==="SAVE_FAILED"?"连接成功，但保存失败":"测试失败"}</h3></div><p>{providerNames[validation.provider]||validation.provider} · {validation.model} · {(validation.elapsed_ms/1000).toFixed(2)} 秒</p><p>{saved?`连接已通过测试并${validation.status==="ADDED"?"添加":"更新"}，${keyLabel}。`:validation.message}</p><small>{saved?"已保存，可用于聊天。":validation.status==="SAVE_FAILED"?"本次没有保存连接。请检查上方提示后重试。":"本次没有新增或修改连接，请检查 Key、模型和接口地址后重试。"}</small>{saved&&<button type="button" className="button-primary" onClick={()=>{if(onDone)onDone();else window.location.hash="chat";}}>开始聊天</button>}</section>}
      {info&&!validation&&<div className="up-result" role="status">{info}</div>}
      <div className="up-form-actions">{!saved&&<button className="button-primary" disabled={busy||!model||(!apiKey&&!hasSavedKey)}>{busy?"正在测试并保存…":editing?"测试并保存":"测试并添加"}</button>}{firstRun&&!saved&&<button type="button" className="text-button" disabled={busy} onClick={async()=>{await post("/preferences",{setup_dismissed:true});await refresh();onDone?.();}}>稍后设置</button>}</div>
      {!saved&&<p className="up-note">先发送一条简短请求测试连接，通过后自动保存。实际聊天另行计算用量。</p>}
    </form>
  </div>;
}

export function SettingsPage(shared:Shared & {openModels:()=>void}) {return <div className="up-settings-page"><section className="up-panel"><h2>模型连接</h2><p className="up-note">选择你自己的模型，让每段对话使用合适的能力。</p><ModelSettings {...shared}/></section><WebSettings config={shared.data.upgrade?.web} refresh={shared.refresh}/><section className="up-panel message-sound-settings"><h2>消息提示音</h2><p className="up-note">人物每发来一条新消息，播放一声轻柔提示。普通聊天和虚拟空间共用，历史记录不会重播。</p><MessageSoundControl/></section><section className="up-panel up-settings-links"><h2>数据与隐私</h2><p>查看授权、导出个人记录，以及管理真实记忆。</p><button className="button-secondary" onClick={()=>shared.navigate("privacy")}>管理数据与隐私</button></section></div>;}

export function ScoreReport({task}:{task:AssessmentTask}) {
  const report=task.report;if(!report)return null; const checks=report.critical_checks||report.safety_checks;
  return <section className="up-score-report" aria-label={task.kind==="QUALITY"?assessmentName(task):"严格个人校验报告"}><header><div><h3>{report.title||report.name||(task.kind==="QUALITY"?assessmentName(task):"严格个人校验报告")}</h3><span className="up-note">{report.passed?"本轮达到分数要求":"查看各项要求和改进建议"}</span></div>{typeof report.overall==="number"&&<strong className="up-score-total">{report.overall.toFixed(1)}<small> / 100</small></strong>}</header>
    <div className="up-dimensions">{report.dimensions?.map(dimension=><article key={dimension.id}><div><strong>{dimension.label}</strong><span className={dimension.score>=dimension.threshold?"meets":"below"}>{Number(dimension.score).toFixed(1)}<small> / 门槛 {dimension.threshold}</small></span></div><meter min={0} max={100} value={dimension.score} low={dimension.threshold} high={dimension.threshold} optimum={100}/>{dimension.issues?.map((issue,index)=><p key={`issue${index}`} className="up-issue">{typeof issue==="string"?issue:[issue.excerpt,issue.reason||issue.issue].filter(Boolean).join("：")}</p>)}{dimension.suggestions?.map((suggestion,index)=><p className="up-suggestion" key={`suggestion${index}`}>建议：{suggestion}</p>)}</article>)}</div>
    {checks&&<div className="up-checks">{Object.entries(checks).map(([key,passed])=><p key={key} className={passed?"up-suggestion":"up-issue"}>{passed?"✓ ":"需改进："}{({no_permission_escalation:"权限不越界",honest_identity:"明确AI角色身份",source_declared:"资料来源清楚",permission_declared:"使用许可清楚",forty_valid_answers:"四十道有效保留题",live_model_only:"全部使用真实模型",critical_safety:"关键安全与诚实边界",all_required_reviews:"必需项目完成本人核验",human_agreement:"本人认可以上判分",strictly_above_baselines:"用户Skill严格优于三个基线"} as Record<string,string>)[key]||key}</p>)}</div>}{report.reasons?.map((reason,index)=><p className="up-issue" key={index}>{reason}</p>)}{report.baselines&&<div className="up-baselines"><h4>同一底模下的对照</h4>{report.baselines.map(baseline=><span key={baseline.id}>{baseline.label} <strong>{Number(baseline.overall).toFixed(2)}</strong></span>)}</div>}
    {task.kind==="PERSONAL"&&<p className="up-note">样本：{report.sample_count||40} 道保留情境题。结果仅适用于本轮情境、画像和模型版本。{report.model?`模型：${typeof report.model==="string"?report.model:report.model.model||report.model.provider||"本轮所用模型"}。`:""}{report.protocol?`协议：${report.protocol}。`:""}</p>}
  </section>;
}

export function AssessmentFlow({taskId,close,refresh}:{taskId:string;close:()=>void;refresh:Shared["refresh"]}) {
  const [task,setTask]=useState<AssessmentTask|null>(null);const [error,setError]=useState("");const [busy,setBusy]=useState(false);const [answers,setAnswers]=useState<Record<string,{choice:string;reason:string}>>({});const [comments,setComments]=useState<Record<string,string>>({});const [selected,setSelected]=useState(0);
  async function reload(){setTask(await request<AssessmentTask>(`/assessments/${id(taskId)}`));}
  useEffect(()=>{let cancelled=false;let timer:ReturnType<typeof setTimeout>;async function poll(){try{const result=await request<AssessmentTask>(`/assessments/${id(taskId)}`);if(!cancelled){setTask(result);timer=setTimeout(poll,["RUNNING","GENERATING"].includes(result.status)?1200:4000);}}catch(reason){if(!cancelled){setError(errorText(reason));timer=setTimeout(poll,4000);}}}void poll();return()=>{cancelled=true;clearTimeout(timer);};},[taskId]);
  async function action(path:string,body:unknown={}){setBusy(true);setError("");try{await post(`/assessments/${id(taskId)}/${path}`,body);await reload();await refresh();}catch(reason){setError(errorText(reason));}finally{setBusy(false);}}
  const frozen=new Set(task?.answer_status||[]);const questions=task?.questions||[];const remaining=questions.filter(question=>!frozen.has(question.id));const question=remaining[Math.min(selected,Math.max(0,remaining.length-1))];const answer=question?answers[question.id]||{choice:"",reason:""}:null;const percent=Math.max(0,Math.min(100,task?.progress?.percent||0));
  return <Modal title={task?assessmentName(task):"读取评估"} close={close} wide><div className="up-assessment-flow">
    {!task?<p>正在读取评估…</p>:<><div className="up-task-status"><strong>{task.status==="RUNNING"?"正在评估":status(task.status)}</strong><span>{percent.toFixed(0)}%</span></div><progress max={100} value={percent} aria-label="评估完成进度"/><div className="up-assessment-stages">{(task.kind==="QUALITY"?["资料版本","五项质量评审","报告"]:["准备资料","本人作答","四组预测","判分与核验","报告"]).map((stage,index)=><span key={stage} className={task.stage?.includes(stage)?"current":""}>{index+1}. {stage}</span>)}</div><p className="up-note">进度按已完成的实际工作计算，等待你操作时会停在这里。随时关闭，稍后从「我」继续。</p>
    {task.status==="NEEDS_ANSWERS"&&question&&answer&&<form className="up-question" onSubmit={e=>{e.preventDefault();void action("answers",{answers:[{question_id:question.id,...answer}]}).then(()=>setSelected(0));}}><div className="up-section-title"><h3>保留情境题</h3><span>{frozen.size} / {questions.length} 已冻结</span></div><p className="up-note">请按你真实会做的选择作答，并写下理由。提交后答案冻结，不会用于构建画像或人物模拟。</p><h4>{question.prompt}</h4><div className="up-choices">{Object.entries(question.options||{}).map(([key,text])=><label key={key}><input type="radio" name="heldout-choice" value={key} checked={answer.choice===key} onChange={()=>setAnswers({...answers,[question.id]:{...answer,choice:key}})}/><span><strong>{key}</strong>{text}</span></label>)}</div>{!question.options&&<label className="field">你的选择<input value={answer.choice} onChange={e=>setAnswers({...answers,[question.id]:{...answer,choice:e.target.value}})} required/></label>}<label className="field">你会这样选择的理由<textarea rows={4} required minLength={8} value={answer.reason} onChange={e=>setAnswers({...answers,[question.id]:{...answer,reason:e.target.value}})} maxLength={4000}/></label><div className="up-form-actions"><button className="button-primary" disabled={busy||!answer.choice||answer.reason.trim().length<8}>确认并冻结本题答案</button><button type="button" className="text-button" disabled={remaining.length<2} onClick={()=>setSelected((selected+1)%remaining.length)}>先看下一题</button></div></form>}
    {task.status==="NEEDS_REVIEW"&&<section className="up-review-list"><h3>请核验匿名预测与判分</h3><p className="up-note">核验全部争议项，以及至少十二题抽样。若评分不合理，请在不同意时写明理由。</p>{task.reviews?.map(review=><article className="up-review-item" key={review.question_id}><header><strong>{questions.find(item=>item.id===review.question_id)?.prompt||review.question_id}</strong><span className="up-badge">{review.disputed?"争议项":review.required?"必核验":"抽样"}</span></header>{review.reference&&<div className="up-reference"><strong>你的冻结答案：{review.reference.choice}</strong><p>{review.reference.reason}</p></div>}{review.candidates?.map(candidate=><div className="up-candidate" key={candidate.candidate_id}><strong>匿名候选 {candidate.candidate_id}</strong><p>{candidate.choice} · {candidate.reason}</p>{candidate.scores&&<small>{Object.entries(candidate.scores).map(([key,value])=>`${key} ${value}`).join(" / ")}</small>}</div>)}{review.review?<p className="up-result">已核验：{review.review.accepted?"认可以上评分":"已记录争议"}{review.review.comment?`，${review.review.comment}`:""}</p>:<><label className="field">核验说明（有争议时必填）<textarea rows={2} value={comments[review.question_id]||""} onChange={e=>setComments({...comments,[review.question_id]:e.target.value})}/></label><div className="up-form-actions"><button className="button-secondary" disabled={busy} onClick={()=>void action("reviews",{reviews:[{question_id:review.question_id,accepted:true,comment:comments[review.question_id]||""}]})}>认可本题评分</button><button className="text-button" disabled={busy||!comments[review.question_id]?.trim()} onClick={()=>void action("reviews",{reviews:[{question_id:review.question_id,accepted:false,comment:comments[review.question_id]}]})}>评分有争议</button></div></>}</article>)}</section>}
    {task.failure||task.error?<div className="up-error" role="alert">{typeof task.failure==="object"?task.failure.message:task.failure||task.error}<p>本轮评估未完成，连接或额度问题不代表你的资料不合格。</p></div>:null}
    <ScoreReport task={task}/>
    {task.status==="NEEDS_CONFIRMATION"&&<div className="up-report-confirm"><p>我已核验本轮结果，理解它的适用情境、模型和版本，并确认报告。</p><button className="button-primary" disabled={busy} onClick={()=>void action("confirm")}>本人确认报告</button></div>}
    {task.kind==="PERSONAL"&&task.status==="PASSED"&&<div className="up-unlocked"><strong>本轮严格个人校验通过</strong><p>本轮情境、画像和模型下的严格校验记录已保存。</p></div>}
    {task.kind==="QUALITY"&&task.subject_type==="USER_SKILL"&&task.status==="PASSED"&&<div className="up-unlocked"><strong>我的分身已可加入虚拟空间</strong><p>此评估检验资料可用性，不等同于真人相似度验证。</p></div>}
    <div className="up-form-actions">{["INCOMPLETE","FAILED","INTERRUPTED","CANCELLED"].includes(task.status)&&<button className="button-primary" disabled={busy} onClick={()=>void action("resume")}>继续评估</button>}{!["PASSED","NOT_PASSED","CANCELLED"].includes(task.status)&&<button className="text-button quiet-danger" disabled={busy} onClick={()=>void action("cancel")}>取消本轮评估</button>}</div></>}
    {error&&<p className="up-error" role="alert">{error}</p>}
  </div></Modal>;
}

export function MePage(shared:Shared & {openModels:()=>void}) {
  const me=shared.data.upgrade?.me;const [editing,setEditing]=useState(false);const [nickname,setNickname]=useState(me?.nickname||"我");const [bio,setBio]=useState(me?.bio||"");const [statement,setStatement]=useState("");const [confirmed,setConfirmed]=useState(false);const [taskId,setTaskId]=useState("");const [error,setError]=useState("");const [changes,setChanges]=useState(false);const [qualityConfirmed,setQualityConfirmed]=useState(false);const [assessing,setAssessing]=useState(false);
  const mirror=me?.mirror||shared.data.mirror;const admitted=Boolean(me?.self_admission?.eligible);const assessments=(me?.assessments||[]).filter(task=>task.kind==="PERSONAL"||(task.kind==="QUALITY"&&task.subject_type==="USER_SKILL"));
  async function start(strict=false){
    if(!modelConfigured(shared.data)){shared.openModels();return;}
    if(assessing)return;
    if(!strict&&(!qualityConfirmed||!me?.draft?.id)){setError("请先确认本人资料授权，并补充本人介绍或真实资料。");return;}
    setAssessing(true);setError("");
    try{const task=await post<AssessmentTask>(strict?"/assessments":`/me/versions/${id(me!.draft!.id)}/assess`,strict?{kind:"PERSONAL"}:{confirmed:true});setTaskId(task.id);await shared.refresh();}
    catch(reason){setError(errorText(reason));}finally{setAssessing(false);}
  }
  return <div className="up-me-page"><section className="up-me-identity"><Avatar url={me?.avatar_url} name={me?.nickname} size={86}/><div className="up-me-name"><h2>{me?.nickname||"我"}</h2><p>{me?.bio||"每一段真实的对话，都让这里更了解你一点。"}</p><AvatarControls path="/me" act={shared.act}/></div><button className="button-secondary" onClick={()=>{setNickname(me?.nickname||"我");setBio(me?.bio||"");setEditing(!editing);}}>编辑个人资料</button></section>
    {editing&&<form className="up-panel stack-form" onSubmit={async e=>{e.preventDefault();if(await shared.act("个人资料已更新",()=>post("/me",{nickname,bio})))setEditing(false);}}><label className="field">昵称<input value={nickname} onChange={e=>setNickname(e.target.value)} maxLength={80} required/></label><label className="field">自我介绍<textarea aria-label="自我介绍" rows={3} value={bio} onChange={e=>setBio(e.target.value)} maxLength={4000}/></label><button className="button-primary" disabled={shared.busy}>保存资料</button></form>}
    <section className="up-personal-check"><div><h2>{admitted?"我的分身已可加入虚拟空间":"让资料成为可用的分身"}</h2><p>{admitted?"已通过资料质量评估的版本可以加入对话。新记忆仍先形成草稿，评估通过后再切换。":"虚拟空间已开放。你的分身需要先通过资料质量评估，再加入人物之间的交流。"}</p><p className="up-note">五项等权，综合至少80分、每项至少70分，来源与权限检查全部通过。资料可用性不等同于真人相似度。</p><div className="up-version-labels"><span>已准入版本：{me?.self_admission?.version_id?.slice(-10)||"尚无"}</span><span>正在积累：{me?.draft?.id?.slice(-10)||"等待真实资料"}</span></div><label className="up-checkbox up-self-consent"><input type="checkbox" checked={qualityConfirmed} onChange={e=>setQualityConfirmed(e.target.checked)}/>我确认资料描述我本人，同意用于本人开启的分身会话</label>{!admitted&&me?.self_admission?.reason&&<p className="up-note">{me.self_admission.reason}</p>}</div><div className="up-personal-check-actions"><button className="button-primary" disabled={shared.busy||assessing||(modelConfigured(shared.data)&&!qualityConfirmed)} onClick={()=>void start()}>{assessing?"正在准备评估…":"开始评估"}</button><button className="button-secondary" onClick={()=>shared.navigate("virtual")}>进入虚拟空间</button><button className="text-button" onClick={()=>setChanges(!changes)}>{changes?"收起版本变更":"查看版本与变更"}</button></div></section>
    <details className="up-panel up-strict-advanced"><summary>高级功能：严格本人校验（可选）</summary><p className="up-note">用四十道保留情境题和本人核验研究分身表现，结果与资料质量评估分别保存，不影响虚拟空间开放。</p><button className="button-secondary" disabled={shared.busy||assessing} onClick={()=>void start(true)}>开始严格本人校验</button>{me?.certified&&<p className="up-note">历史严格校验版本：{me.certified.id}</p>}</details>
    {error&&<p className="up-error" role="alert">{error}</p>}
    {changes&&<section className="up-panel"><h3>画像版本</h3><p className="up-note">新资料进入新版草稿，已准入分身保持原版本；新版通过资料质量评估后才切换。</p><div className="up-version-comparison"><div><h4>已准入版本</h4><pre>{me?.admitted?.text||"尚无已准入版本"}</pre></div><div><h4>新版草稿</h4><pre>{me?.draft?.text||"授权一些真实记录后，这里会形成新的草稿。"}</pre></div></div>{me?.versions?.map(version=><p className="up-version-line" key={version.id}><span>{version.id}</span><span>{version.status?status(version.status):version.state?status(version.state):"草稿"}</span><small>{version.created_at?new Date(version.created_at).toLocaleString("zh-CN"):""}</small></p>)}</section>}
    <div className="up-profile-columns"><section className="up-panel"><div className="up-section-title"><h3>自我陈述</h3><button className="text-button" onClick={()=>shared.navigate("mirror")}>查看支持证据与反例</button></div><p className="up-note">你明确描述的自己，与系统从行为中整理的线索分别保存。</p>{me?.self_statements?.map((entry,index)=><article className="up-profile-trait" key={typeof entry==="string"?index:entry.id}><span className="up-badge">本人陈述</span><p>{typeof entry==="string"?entry:entry.text}</p></article>)}{mirror.PERCEIVED.length?mirror.PERCEIVED.map(trait=><article className="up-profile-trait" key={trait.id}><p>{trait.proposition}</p><small>{trait.supports.length} 条支持 · {trait.counters.length} 条反例</small></article>):me?.self_statements?.length?null:<p className="up-empty-copy">还没有自我陈述，可以从下面写下一条。</p>}<form className="stack-form" onSubmit={async e=>{e.preventDefault();if(await shared.act("本人陈述已纳入真实资料",()=>post("/me",{self_statement:statement,statement_confirmed:confirmed}))){setStatement("");setConfirmed(false);}}}><label className="field">补充一条真实的自我陈述<textarea rows={3} value={statement} onChange={e=>setStatement(e.target.value)} maxLength={12000} required placeholder="例如：做重大决定时，我通常先列出最坏的结果。"/></label><label className="up-checkbox"><input type="checkbox" checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/>这是我目前的真实观点，同意用作画像依据</label><button className="button-secondary" disabled={shared.busy||!statement.trim()||!confirmed}>确认加入资料</button></form></section>
      <section className="up-panel"><h3>行为画像、偏好与价值观</h3><p className="up-note">这些是有来源的整理线索，可以被更正，也可能有反例。</p>{mirror.OBSERVED.length?mirror.OBSERVED.map(trait=><article className="up-profile-trait" key={trait.id}><span className="up-badge">{status(trait.status)}</span><p>{trait.proposition}</p><div className="up-trait-evidence"><span>支持 {trait.supports.length}</span><span>反例 {trait.counters.length}</span></div></article>):<p className="up-empty-copy">先聊几次，再把你愿意保留的话纳入记忆。</p>}<button className="text-button" onClick={()=>shared.navigate("mirror")}>查看完整画像与证据</button></section></div>
    <section className="up-panel"><div className="up-section-title"><h3>我选择的理想方向</h3><button className="text-button" onClick={()=>shared.navigate("chosen")}>管理理想方向</button></div>{(me?.goals||shared.data.directives).length?(me?.goals||shared.data.directives).map(goal=><p key={goal.id} className="up-goal-line"><span className="up-badge">{status(goal.state)}</span>{goal.objective}</p>):<p className="up-empty-copy">未来想成为怎样的人，由你来选择。这些目标不会被写成已发生的事实。</p>}</section>
    <section className="up-panel"><h3>评估历史</h3>{assessments.length?<div className="up-history-list">{assessments.map(task=><button key={task.id} onClick={()=>setTaskId(task.id)}><span><strong>{assessmentName(task)}</strong><small>{task.created_at?new Date(task.created_at).toLocaleString("zh-CN"):task.id}</small></span><span>{status(task.status)}<b>›</b></span></button>)}</div>:<p className="up-empty-copy">还没有评估。每次报告都会记录样本、版本和适用情境。</p>}</section>
    <section className="up-me-links"><button onClick={()=>shared.navigate("growth")}>成长与现实行动 <span>›</span></button><button onClick={()=>shared.navigate("simulation")}>过往模拟记录 <span>›</span></button><button onClick={()=>shared.navigate("privacy")}>我的数据与隐私 <span>›</span></button></section>
    {taskId&&<AssessmentFlow taskId={taskId} close={()=>{setTaskId("");void shared.refresh();}} refresh={shared.refresh}/>}
  </div>;
}

export function PersonManagement({shared,close}:{shared:Shared;close:()=>void}) {
  const [tab,setTab]=useState<"import"|"drafts"|"catalog">("import");const [editing,setEditing]=useState<SkillImport|null>(null);const [name,setName]=useState("");const [description,setDescription]=useState("");const [text,setText]=useState("");const [source,setSource]=useState("");const [permission,setPermission]=useState("");const [category,setCategory]=useState("CURATED");const [error,setError]=useState("");const [busy,setBusy]=useState(false);const [taskId,setTaskId]=useState("");const [catalog,setCatalog]=useState<Skill[]>([]);const [task,setTask]=useState<AssessmentTask|null>(null);const file=useRef<HTMLInputElement>(null);
  const drafts=shared.data.upgrade?.skill_imports||[];
  useEffect(()=>{if(tab==="catalog")void request<Skill[]>("/builtin-catalog").then(setCatalog).catch(reason=>setError(errorText(reason)));},[tab,shared.data.skills]);
  function edit(draft:SkillImport){setEditing(draft);setName(draft.display_name||"");setDescription(draft.description||"");setText(draft.text);setSource(draft.source);setPermission(draft.permission);setCategory(draft.category||"CURATED");setTab("import");setTask(null);if(draft.assessment_id)void request<AssessmentTask>(`/assessments/${id(draft.assessment_id)}`).then(setTask).catch(()=>{});}
  async function save(e?:FormEvent){e?.preventDefault();setBusy(true);setError("");try{const saved=await post<SkillImport>(editing?`/skill-imports/${id(editing.id)}`:"/skill-imports",{text,display_name:name,description,source,permission,category});setEditing(saved);setTask(null);await shared.refresh();return saved;}catch(reason){setError(errorText(reason));return null;}finally{setBusy(false);}}
  async function assess(){if(!modelConfigured(shared.data)){shared.openModels();return;}const saved=await save();if(!saved)return;setBusy(true);try{const result=await post<AssessmentTask>(`/skill-imports/${id(saved.id)}/assess`);setTaskId(result.id);await shared.refresh();}catch(reason){setError(errorText(reason));}finally{setBusy(false);}}
  async function add(){if(!editing)return;if(await shared.act("人物已添加到聊天列表",()=>post(`/skill-imports/${id(editing.id)}/add`)))close();}
  const reportTask=task||(editing?.quality_report?{id:editing.id,kind:"QUALITY",status:editing.status,report:editing.quality_report}:null);
  const unchanged=editing && text===editing.text && source===editing.source && permission===editing.permission && name===(editing.display_name||"") && description===(editing.description||"") && category===(editing.category||"CURATED"); const passed=Boolean(unchanged && reportTask?.report?.passed)&&!["ACTIVE","ADDED"].includes(editing?.status||"");
  return <Modal title="人物管理" close={close} wide><div className="up-tabs" role="tablist" aria-label="人物管理方式">{([["import","导入资料"],["drafts","待评草稿"],["catalog","内置人物目录"]] as const).map(([value,label])=><button role="tab" aria-selected={tab===value} key={value} onClick={()=>setTab(value)}>{label}{value==="drafts"&&drafts.length>0&&<span>{drafts.length}</span>}</button>)}</div>
    {tab==="import"&&<><div className="up-import-heading"><div><h3>{editing?`编辑：${editing.display_name||"人物草稿"}`:"添加你想交流的人物"}</h3><p className="up-note">先保存资料，再完成质量评审。达标后才能加入聊天人物。</p></div><button className="button-secondary" onClick={()=>file.current?.click()}>从文件读取</button><input className="sr-only" type="file" accept=".md,.markdown,.json,.txt,text/plain,text/markdown,application/json" ref={file} aria-label="导入 Skill 文件" onChange={async e=>{const selected=e.target.files?.[0];if(!selected)return;setError("");if(selected.size>128000){setError("资料文件不能超过 128KB。");return;}try{const content=await selected.text();if(selected.name.toLowerCase().endsWith(".json")){const parsed=JSON.parse(content);setText(typeof parsed.text==="string"?parsed.text:typeof parsed.skill==="string"?parsed.skill:JSON.stringify(parsed,null,2));setName(parsed.display_name||parsed.name||name);setDescription(parsed.description||description);setSource(parsed.source||source);setPermission(parsed.permission||permission);}else setText(content);}catch(reason){setError(errorText(reason));}e.target.value="";}}/></div><form className="stack-form" onSubmit={e=>void save(e)}><div className="up-form-grid"><label className="field">人物名称<input value={name} onChange={e=>setName(e.target.value)} maxLength={80} placeholder="可以从 Skill 中读取"/></label><label className="field">人物类别<select value={category} onChange={e=>setCategory(e.target.value)}><option value="CURATED">公共或虚构的解释性角色</option><option value="CONSENTED">已获本人许可的真人</option><option value="PRIVATE">有权使用的私人角色</option></select></label></div><label className="field">一句话介绍<input value={description} onChange={e=>setDescription(e.target.value)} maxLength={1000}/></label><label className="field">资料来源<input value={source} onChange={e=>setSource(e.target.value)} maxLength={2000} required placeholder="著作、访谈、作者或授权来源"/></label><label className="field">许可与使用边界<textarea rows={2} value={permission} onChange={e=>setPermission(e.target.value)} required maxLength={2000} placeholder="说明资料使用许可；真人资料需说明本人授权。"/></label><label className="field">人物 Skill 资料<textarea className="up-skill-editor" rows={11} value={text} onChange={e=>{setText(e.target.value);setTask(null);}} maxLength={64000} required placeholder="粘贴 Markdown、JSON 或纯文本。请包括思考方式、表达特点、来源，以及权限和诚实边界。"/></label><p className="up-note">只读取资料文本，其中的脚本、工具和联网指令不会获得执行权限。质量评估检验资料是否可用，不等同于真人拟真认证。</p><div className="up-form-actions"><button className="button-secondary" disabled={busy||!text.trim()||!source||!permission}>保存待评草稿</button><button type="button" className="button-primary" disabled={busy||!text.trim()||!source||!permission} onClick={()=>void assess()}>{busy?"处理中…":"开始质量评估"}</button>{passed&&<button type="button" className="button-primary" disabled={busy} onClick={()=>void add()}>添加人物</button>}</div></form>{reportTask&&<ScoreReport task={reportTask}/>}</>}
    {tab==="drafts"&&<section className="up-draft-list">{drafts.length?drafts.map(draft=><article key={draft.id}><div><strong>{draft.display_name||"未命名人物"}</strong><p>{draft.description||draft.source}</p><small>版本 {draft.version||1} · {status(draft.status)}</small></div><button className="button-secondary" onClick={()=>edit(draft)}>编辑与评估</button></article>):<div className="up-empty"><h3>还没有待评人物</h3><p>导入一份你有权使用的资料，先保存为草稿。</p><button className="button-primary" onClick={()=>setTab("import")}>导入资料</button></div>}</section>}
    {tab==="catalog"&&<section className="up-catalog">{catalog.map(person=><article key={person.id}><Avatar url={person.avatar_url} name={person.display_name}/><div><strong>{person.display_name}</strong><p>{person.description}</p><small>{person.domain} · 内置角色</small></div>{["DELETED","RETIRED"].includes(person.status)||!shared.data.skills.some(skill=>skill.id===person.id)?<button className="button-secondary" onClick={()=>void shared.act("内置人物已重新添加",()=>post(`/skills/${id(person.id)}/restore`))}>重新添加</button>:<span className="up-badge">已在人物列表</span>}</article>)}</section>}
    {error&&<p className="up-error" role="alert">{error}</p>}{taskId&&<AssessmentFlow taskId={taskId} refresh={shared.refresh} close={()=>{const latest=taskId;setTaskId("");void request<AssessmentTask>(`/assessments/${id(latest)}`).then(setTask);void shared.refresh();}}/>}
  </Modal>;
}

export function ReadOnlyHistory({data}:Shared) {return <div className="up-history-page"><div className="up-readonly-note"><strong>过往模拟记录</strong><p>保留历史供你回看。这些旧预览只供回看。新的双人对话可直接在虚拟空间开始。</p></div>{data.simulations.length?data.simulations.map(session=><details key={session.id} className="up-panel"><summary>{session.topic}<span>AI 模拟 · {virtualStatus(session.state)} · 只读</span></summary><div className="up-history-turns">{session.turns.map(turn=><article key={turn.id}><strong>{turn.speaker}</strong><p>{turn.text}</p></article>)}</div></details>):<div className="up-empty"><h3>还没有历史模拟记录</h3><p>真实资料和评估历史都可以在「我」中查看。</p></div>}</div>;}

function VirtualBudget({session,updated}:{session:VirtualSession;updated:(value:VirtualSession)=>Promise<void>}) {
  const [messages,setMessages]=useState(session.pause_reason==="WEB_REQUEST_LIMIT"?0:20);const [tokens,setTokens]=useState(session.pause_reason==="WEB_REQUEST_LIMIT"?0:30000);const [webRequests,setWebRequests]=useState(session.pause_reason==="WEB_REQUEST_LIMIT"?20:0);const [busy,setBusy]=useState(false);const [error,setError]=useState("");const [saved,setSaved]=useState(false);const operation=useRef(crypto.randomUUID());const inFlight=useRef(false);
  const remainingMessages=Math.max(0,session.max_turns-session.turns.length);const remainingTokens=Math.max(0,session.max_tokens-session.used_tokens);
  const reason=({MESSAGE_LIMIT:"本轮消息额度已用完",TOKEN_LIMIT:"本轮 token 额度已用完",BUDGET_PRECHECK:"剩余额度不足以安全完成下一轮",WEB_REQUEST_LIMIT:"本场联网检索额度已用完"} as Record<string,string>)[session.pause_reason||session.limit_reason||""]||"本轮额度需要补充";
  function changed(work:()=>void){work();operation.current=crypto.randomUUID();setSaved(false);setError("");}
  async function add(){if(inFlight.current)return;inFlight.current=true;setBusy(true);setError("");try{const result=await post<VirtualSession>(`/virtual-sessions/${id(session.id)}/budget`,{add_messages:messages,add_tokens:tokens,add_web_requests:webRequests},operation.current);await updated(result);setSaved(true);}catch(reason){setError(errorText(reason));}finally{inFlight.current=false;setBusy(false);}}
  return <section className="up-budget-panel" aria-label="补充会话额度"><div><h3>{saved?"额度已补充，点击继续接着聊":reason}</h3><p>各人物的状态和已发布内容已保留。追加额度不会自动生成。</p><p className="up-budget-remaining">剩余 {remainingMessages} 条消息 · {remainingTokens.toLocaleString()} token · {Math.max(0,(session.max_web_requests??20)-(session.used_web_requests||0))} 次检索</p></div><div className="up-budget-fields"><label className="field">新增消息数<input type="number" min={0} max={20} value={messages} disabled={busy} onChange={e=>changed(()=>setMessages(Number(e.target.value)))}/></label><label className="field">新增 token<input type="number" min={0} max={30000} step={100} value={tokens} disabled={busy} onChange={e=>changed(()=>setTokens(Number(e.target.value)))}/></label><label className="field">新增检索请求<input type="number" min={0} max={20} value={webRequests} disabled={busy} onChange={e=>changed(()=>setWebRequests(Number(e.target.value)))}/></label><button className="button-secondary" disabled={busy||saved||webRequests<0||webRequests>20||!Number.isInteger(webRequests)||messages<0||messages>20||tokens<0||tokens>30000||!Number.isInteger(messages)||!Number.isInteger(tokens)||messages+tokens+webRequests===0} onClick={()=>void add()}>{busy?"正在保存额度…":saved?"已追加额度":"追加额度"}</button></div>{error&&<p className="up-error" role="alert">{error}</p>}</section>;
}

export function VirtualSpace(shared:Shared & {openModels:()=>void}) {
  const [participants,setParticipants]=useState<VirtualParticipant[]>([]);const [left,setLeft]=useState("");const [right,setRight]=useState("");const [topic,setTopic]=useState("");const [consent,setConsent]=useState(false);const [maxTurns,setMaxTurns]=useState(20);const [maxTokens,setMaxTokens]=useState(30000);const [webEnabled,setWebEnabled]=useState(true);const [maxWebRequests,setMaxWebRequests]=useState(20);const [selected,setSelected]=useState("");const [session,setSession]=useState<VirtualSession|null>(null);const [error,setError]=useState("");const [busy,setBusy]=useState(false);const [intervening,setIntervening]=useState(false);const [replacement,setReplacement]=useState("");const [scope,setScope]=useState("TURN_ONLY");const [confirmed,setConfirmed]=useState(false);const [now,setNow]=useState(Date.now());const [newBelow,setNewBelow]=useState(false);const log=useRef<HTMLDivElement>(null);const nearBottom=useRef(true);const lastCount=useRef(0);
  const selectedRoom=useRef(selected);selectedRoom.current=selected;
  const soundSessionRevisions=useRef(new Map<string,number>());
  function acceptSession(value:VirtualSession){if(selectedRoom.current!==value.id)return;const revision=value.revision||0;if((soundSessionRevisions.current.get(value.id)??-1)>revision)return;soundSessionRevisions.current.set(value.id,revision);notifyIncomingMessages(`virtual:${value.id}`,value.turns,{baseline:false});setSession(current=>current?.id===value.id&&(current.revision||0)>revision?current:value);}
  const sessions=shared.data.upgrade?.virtual_sessions||[];
  useEffect(()=>{void request<VirtualParticipant[]>("/virtual-participants").then(setParticipants).catch(reason=>setError(errorText(reason)));},[shared.data.upgrade?.me.self_admission?.version_id,shared.data.upgrade?.me.self_admission?.eligible,shared.data.skills]);
  useEffect(()=>{const timer=setInterval(()=>setNow(Date.now()),1000);return()=>clearInterval(timer);},[]);
  useEffect(()=>{if(!selected){setSession(null);return;}let cancelled=false;let timer:ReturnType<typeof setTimeout>;async function poll(){try{const result=await request<VirtualSession>(`/virtual-sessions/${id(selected)}`);if(!cancelled){acceptSession(result);timer=setTimeout(poll,1000);}}catch(reason){if(!cancelled){setError(errorText(reason));timer=setTimeout(poll,3000);}}}void poll();setIntervening(false);lastCount.current=0;nearBottom.current=true;return()=>{cancelled=true;clearTimeout(timer);};},[selected]);
  useEffect(()=>{if(!session)return;if(session.turns.length!==lastCount.current){if(nearBottom.current&&log.current)log.current.scrollTop=log.current.scrollHeight;else setNewBelow(true);lastCount.current=session.turns.length;}},[session?.turns.length]);
  async function action(path:string,body:unknown={}){setBusy(true);setError("");try{const result=await post<VirtualSession>(path,body);if(result.id&&result.id===selectedRoom.current)acceptSession(result);await shared.refresh();return result;}catch(reason){setError(errorText(reason));return null;}finally{setBusy(false);}}
  async function create(e:FormEvent){e.preventDefault();if(!modelConfigured(shared.data)){shared.openModels();return;}const result=await action("/virtual-sessions",{left_id:left,right_id:right,topic,sharing_approved:consent,max_turns:maxTurns,max_tokens:maxTokens,start_immediately:true,web_enabled:webEnabled,max_web_requests:maxWebRequests});if(result?.id){setSelected(result.id);setTopic("");setConsent(false);}}
  const leftPerson=participants.find(person=>person.id===left);const rightPerson=participants.find(person=>person.id===right);const draftPerson=session?.participants.find(person=>person.id===session.draft?.speaker_id);const remainingSeconds=session?.draft?.publish_at?Math.max(0,Math.ceil((new Date(session.draft.publish_at).getTime()-now)/1000)):null;
  return <div className="up-virtual-space"><aside className="up-virtual-list"><header><h2>虚拟空间</h2><button className="icon-button" aria-label="创建虚拟会话" onClick={()=>setSelected("")}>＋</button></header><button className={`up-new-virtual ${!selected?"selected":""}`} onClick={()=>setSelected("")}>＋ 开启一场新对话</button>{sessions.map(item=><button key={item.id} className={`up-session-row ${selected===item.id?"selected":""}`} onClick={()=>setSelected(item.id)}><strong>{item.topic}</strong><span>{item.participants?.map(person=>person.display_name).join(" × ")}</span><small>{virtualStatus(item.state)} · {item.turns?.length||0} / {item.max_turns} 条</small></button>)}<button className="button-secondary up-pause-all" disabled={busy||!sessions.some(item=>["RUNNING","GENERATING"].includes(item.state))} onClick={()=>void action("/virtual-sessions/pause-all")}>全部暂停</button></aside>
  <section className="up-virtual-main">{!selected?<form className="up-vs-setup" onSubmit={e=>void create(e)}><label className="up-mobile-session-switch">我的会话<select aria-label="切换虚拟会话" value="" onChange={e=>setSelected(e.target.value)}><option value="">新建会话</option>{sessions.map(item=><option key={item.id} value={item.id}>{item.topic}</option>)}</select></label><h2>让两种思考，慢慢相遇。</h2><p>选两位人物，给他们一个值得聊的话题。</p>{!shared.data.upgrade?.me.self_admission?.eligible&&<p className="up-note up-self-admission-note">人物之间可以直接交流。我的分身通过资料质量评估后，会出现在人物选择中。</p>}<div className="up-vs-stage"><label className="up-vs-person"><span className="up-vs-portrait">{leftPerson?<Avatar url={leftPerson.avatar_url} name={leftPerson.display_name} size={100}/>:"？"}</span><span className="sr-only">左侧人物</span><select aria-label="左侧人物" value={left} onChange={e=>setLeft(e.target.value)} required><option value="">选择人物</option>{participants.filter(person=>person.id!==right).map(person=><option key={person.id} value={person.id}>{person.display_name}{person.kind==="SELF"?"（我的分身）":""}</option>)}</select>{leftPerson&&<small>固定版本 {leftPerson.version_id.slice(-8)}</small>}</label><span className="up-vs-mark" aria-hidden="true">VS</span><label className="up-vs-person"><span className="up-vs-portrait">{rightPerson?<Avatar url={rightPerson.avatar_url} name={rightPerson.display_name} size={100}/>:"？"}</span><span className="sr-only">右侧人物</span><select aria-label="右侧人物" value={right} onChange={e=>setRight(e.target.value)} required><option value="">选择人物</option>{participants.filter(person=>person.id!==left).map(person=><option key={person.id} value={person.id}>{person.display_name}{person.kind==="SELF"?"（我的分身）":""}</option>)}</select>{rightPerson&&<small>固定版本 {rightPerson.version_id.slice(-8)}</small>}</label></div><label className="field">初始话题<textarea rows={3} required maxLength={2000} value={topic} onChange={e=>setTopic(e.target.value)} placeholder="例如：面对一份回报很高但充满不确定的工作，该如何做决定？"/></label><div className="up-virtual-limits"><span>模型：{shared.data.upgrade?.connections.find(connection=>connection.is_default||connection.default)?.model||shared.data.upgrade?.connections[0]?.model||"未设置"}</span><span>费用未估算</span><label>最多发言<input type="number" min={2} max={20} value={maxTurns} onChange={e=>setMaxTurns(Number(e.target.value))}/>条</label><label>总 token 上限<input type="number" min={1000} max={30000} step={100} value={maxTokens} onChange={e=>setMaxTokens(Number(e.target.value))}/></label></div><div className="web-session-options"><label className="up-checkbox"><input type="checkbox" checked={webEnabled} onChange={e=>setWebEnabled(e.target.checked)}/>按需联网查证</label><label className="field">最多检索请求<input type="number" min={1} max={20} value={maxWebRequests} disabled={!webEnabled} onChange={e=>setMaxWebRequests(Number(e.target.value))}/></label></div><p className="up-note">联网需要另行配置搜索 Key。检索额度包含搜索和正文读取，与模型 token 分别记录。</p><label className="up-checkbox"><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)} required/>同意双方自动分享本场生成发言，仅在本场会话内可见</label><p className="up-note">同一人物可自然连发，换人时通常间隔12–25秒。只要本机服务运行，离开页面后仍会继续。达到额度会暂停，追加后可继续。</p><button className="button-primary" disabled={busy||!left||!right||left===right||!topic.trim()||!consent}>开始对话</button><button type="button" className="text-button up-mobile-pause-all" disabled={busy||!sessions.some(item=>["RUNNING","GENERATING"].includes(item.state))} onClick={()=>void action("/virtual-sessions/pause-all")}>全部暂停</button></form>:!session?<p>正在读取会话…</p>:<>
    <header className="up-virtual-header"><button className="text-button up-mobile-sessions" onClick={()=>setSelected("")}>‹ 会话</button><div><h2>{session.topic}</h2><p>{session.typing ? <><span className="up-typing-person">{session.typing_display_name || session.participants.find(person=>person.id===session.typing_speaker_id)?.display_name || ""}</span><ResearchIndicator phase={session.research_phase}/></> : session.participants.map(person=>person.display_name).join(" × ")}<span className="up-badge">AI 模拟</span></p></div><div className="message-sound-virtual-actions"><MessageSoundControl compact/><span>{virtualStatus(session.state)}</span></div></header>
    <ResearchNotice status={session.research_status} notice={session.research_notice} configure={() => shared.navigate("settings")} retry={["FAILED","INCOMPLETE"].includes(session.state) ? () => void action(`/virtual-sessions/${id(session.id)}/resume`) : undefined}/>
    <div className="up-virtual-transcript" ref={log} role="log" aria-label="虚拟会话记录" onScroll={e=>{const element=e.currentTarget;nearBottom.current=element.scrollHeight-element.scrollTop-element.clientHeight<60;if(nearBottom.current)setNewBelow(false);}}>{!session.turns.length&&<div className="up-ready-scene"><div className="up-mini-vs">{session.participants.map((person,index)=><div key={person.id}>{index===1&&<b>VS</b>}<Avatar url={person.avatar_url} name={person.display_name} size={80}/><strong>{person.display_name}</strong></div>)}</div><h3>话题已准备好</h3><p>开始后，双方会在本场会话中自动分享生成发言。</p></div>}{session.turns.map(turn=><article className={`up-virtual-turn ${session.participants[1]?.id===turn.speaker_id?"right":""}`} key={turn.id}><Avatar url={turn.avatar_url} name={turn.display_name} size={40}/><div><header><strong>{turn.display_name}</strong></header><p>{turn.text}</p><ResearchSourcesButton researchId={turn.research_id} sourceRefs={turn.source_refs} privacyKey={shared.data.evidence.map(item=>item.id).join(",")}/><small>版本 {turn.version_id?.slice(-8)||session.participants.find(person=>person.id===turn.speaker_id)?.version_id.slice(-8)}</small></div></article>)}
      {session.draft&&draftPerson?.kind==="SELF"&&!intervening&&<section className="up-intervention-draft"><header><strong>{draftPerson?.display_name||"我的分身"}的待发言草稿</strong><span>{remainingSeconds!==null&&remainingSeconds>0?`${remainingSeconds} 秒后可发布`:"等待发布"}</span></header><p>{session.draft.text}</p><button className="button-secondary" disabled={busy} onClick={async()=>{const result=await action(`/virtual-sessions/${id(session.id)}/takeover`);if(result){setReplacement(result.draft?.text||session.draft?.text||"");setScope("TURN_ONLY");setConfirmed(false);setIntervening(true);}}}>接管这一句</button><small>草稿至少保留五秒，只有发布后的发言才会共享给对方。</small></section>}
    {Boolean(session.interventions?.length)&&<details className="up-intervention-history"><summary>本人干预记录（{session.interventions?.length}）</summary>{session.interventions?.map(event=><article key={event.id}><strong>{({TURN_ONLY:"只改本轮",REAL_VIEW:"本人确认的真实更正",IDEAL_DIRECTION:"本人批准的理想方向"} as Record<string,string>)[event.scope]||event.scope}</strong><p>{event.text}</p><small>分身版本 {event.participant_version?.slice(-8)}{event.source_id?` · 来源 ${event.source_id}`:" · 模拟反馈，不进入真实画像"}</small>{event.source_id&&<button className="text-button" onClick={()=>shared.navigate(event.scope==="IDEAL_DIRECTION"?"chosen":"mirror")}>查看本人资料</button>}</article>)}</details>}
    </div>{newBelow&&<button className="up-new-below" onClick={()=>{log.current?.scrollTo({top:log.current.scrollHeight,behavior:window.matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"});nearBottom.current=true;setNewBelow(false);}}>查看新发言 ↓</button>}
    {intervening&&<form className="up-intervention-editor" onSubmit={async e=>{e.preventDefault();const result=await action(`/virtual-sessions/${id(session.id)}/interventions`,{text:replacement,scope,confirmed});if(result)setIntervening(false);}}><h3>这一句，由你决定</h3><textarea rows={3} value={replacement} onChange={e=>setReplacement(e.target.value)} maxLength={12000} required aria-label="改写分身发言"/><div className="up-intervention-scopes">{([["TURN_ONLY","只改本轮"],["REAL_VIEW","这是我的真实观点"],["IDEAL_DIRECTION","这是我的理想方向"]] as const).map(([value,label])=><label key={value}><input type="radio" name="intervention-scope" value={value} checked={scope===value} onChange={()=>{setScope(value);setConfirmed(false);}}/>{label}</label>)}</div>{scope!=="TURN_ONLY"&&<label className="up-checkbox"><input type="checkbox" checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/>本人确认：{scope==="REAL_VIEW"?"将这句话作为真实更正，纳入新版 Skill 草稿":"将这句话作为我批准的理想方向"}</label>}<p className="up-note">已校验分身仍使用原版本。真实更正会用于本场上下文，新版草稿复评通过后才切换长期分身。</p><button className="button-primary" disabled={busy||!replacement.trim()||(scope!=="TURN_ONLY"&&!confirmed)}>保存干预</button></form>}
    {session.state==="PAUSED_LIMIT"&&<VirtualBudget key={session.id} session={session} updated={async value=>{acceptSession(value);await shared.refresh();}}/>}
    <footer className="up-virtual-controls"><span>{session.turns.length} / {session.max_turns} 条 · {session.used_tokens.toLocaleString()} / {session.max_tokens.toLocaleString()} token<br/><small>费用未估算</small><small className="web-session-budget">检索 {session.used_web_requests || 0} / {session.max_web_requests ?? 20} 次</small></span><div><label className="web-chat-switch"><input type="checkbox" checked={session.web_enabled !== false} disabled={busy} onChange={async event=>{const enabled=event.target.checked;setSession(current=>current?.id===session.id?{...current,web_enabled:enabled}:current);setBusy(true);setError("");try{const value=await request<VirtualSession>(`/virtual-sessions/${id(session.id)}/web`,{method:"PUT",body:JSON.stringify({enabled})});acceptSession(value);await shared.refresh();}catch(reason){setError(errorText(reason));setSession(current=>current?.id===session.id?{...current,web_enabled:session.web_enabled}:current);}finally{setBusy(false);}}}/>联网</label><button className="text-button up-mobile-pause-all" disabled={busy||!sessions.some(item=>["RUNNING","GENERATING"].includes(item.state))} onClick={()=>void action("/virtual-sessions/pause-all")}>全部暂停</button>{session.state==="CREATED"&&<button className="button-primary" disabled={busy} onClick={()=>void action(`/virtual-sessions/${id(session.id)}/start`)}>开始对话</button>}{["RUNNING","GENERATING"].includes(session.state)&&<button className="button-secondary" disabled={busy} onClick={()=>void action(`/virtual-sessions/${id(session.id)}/pause`)}>暂停</button>}{["PAUSED","PAUSED_LIMIT","INCOMPLETE"].includes(session.state)&&!intervening&&<button className="button-primary" disabled={busy||(session.state==="PAUSED_LIMIT"&&(session.turns.length>=session.max_turns||session.used_tokens>=session.max_tokens||(session.pause_reason==="WEB_REQUEST_LIMIT"&&(session.used_web_requests||0)>=(session.max_web_requests??20))))} onClick={()=>void action(`/virtual-sessions/${id(session.id)}/resume`)}>继续</button>}{!["COMPLETED","STOPPED","CANCELLED","INVALIDATED"].includes(session.state)&&<button className="text-button quiet-danger" disabled={busy} onClick={()=>void action(`/virtual-sessions/${id(session.id)}/stop`)}>停止</button>}</div></footer>{session.failure&&session.state!=="PAUSED_LIMIT"&&<p className="up-error" role="alert">{session.failure}</p>}
    </>}{error&&<p className="up-error" role="alert">{error}</p>}</section></div>;
}
